export function FileChip(props: {
  name: string;
  size: string;
  isVideo: boolean;
  theme: "light" | "dark";
  accessibleLabel: string;
  tooltip: string;
  suffix?: string | null;
  copyMarkdown?: string;
  disabled?: boolean;
  error?: boolean;
  unresolved?: boolean;
  onOpen?: (() => void) | undefined;
  svgPreview?:
    | {
        file?: Blob | null | undefined;
        environmentId?: EnvironmentId | undefined;
        attachmentId?: string | undefined;
      }
    | undefined;
}) {
  if (props.svgPreview && !props.unresolved) return <SvgFileChip {...props} />;
  const content = <FileChipContent {...props} />;
  const state = props.unresolved
    ? ("unresolved" as const)
    : props.error
      ? ("invalid" as const)
      : null;
  const attributes = {
    kind: props.isVideo ? "video" : (documentChipKindForFileName(props.name) ?? "file"),
    ...(state ? { state } : {}),
    "aria-label": [props.accessibleLabel, props.suffix].filter(Boolean).join(", "),
    "data-markdown-copy": props.copyMarkdown,
    "data-context-unresolved": props.unresolved ? "true" : undefined,
  } as const;
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          props.onOpen ? (
            <ContextChip
              render={<button type="button" disabled={props.disabled} />}
              onClick={props.onOpen}
              {...attributes}
            >
              {content}
            </ContextChip>
          ) : (
            <ContextChip tabIndex={0} {...attributes}>
              {content}
            </ContextChip>
          )
        }
      />
      <TooltipPopup side="top" className="whitespace-pre-wrap">
        {props.tooltip}
      </TooltipPopup>
    </Tooltip>
  );
}

function SvgFileChip(props: ComponentProps<typeof FileChip>) {
  const preview = props.svgPreview;
  const [local, setLocal] = useState<{ file: Blob; url: string }>();
  const [failedPreviewUrl, setFailedPreviewUrl] = useState<string>();
  const asset = useAssetUrlState(
    preview?.file ? null : (preview?.environmentId ?? null),
    preview?.attachmentId
      ? {
          _tag: "attachment",
          attachmentId: preview.attachmentId,
          fileName: props.name,
          mimeType: "image/svg+xml",
          disposition: "inline",
        }
      : null,
  );
  // oxlint-disable-next-line t3code/no-unreasoned-state-sync -- creates an object URL for the local SVG file and revokes it on cleanup
  useEffect(() => {
    const file = preview?.file;
    if (!file) return;
    const url = URL.createObjectURL(file);
    // oxlint-disable-next-line react/set-state-in-effect -- Publish a Blob URL with its cleanup registered.
    setLocal({ file, url });
    return () => URL.revokeObjectURL(url);
  }, [preview?.file]);
  const url = preview?.file
    ? local?.file === preview.file
      ? local.url
      : undefined
    : asset._tag === "Success"
      ? asset.url
      : undefined;
  if (url !== undefined && failedPreviewUrl === url) {
    return <FileChip {...props} svgPreview={undefined} />;
  }
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <ImageChipButton
            name={props.name}
            size={props.size}
            previewUrl={url}
            suffix={props.suffix}
            disabled={props.disabled}
            onClick={props.onOpen}
            onPreviewError={() => setFailedPreviewUrl(url)}
            data-markdown-copy={props.copyMarkdown}
            aria-label={props.accessibleLabel}
            {...(props.error ? { state: "invalid" as const } : {})}
          />
        }
      />
      <TooltipPopup side="top" className="whitespace-pre-wrap">
        {props.tooltip}
      </TooltipPopup>
    </Tooltip>
  );
}

